// Service class being tested
class DiscountService {
    public double calculateDiscount(double price, String customerType) {
        return switch (customerType) {
            case "VIP" -> price * 0.20;      // 20% discount
            case "REGULAR" -> price * 0.10;  // 10% discount
            default -> 0.0;
        };
    }
}

// Unit test using JUnit 5
class DiscountServiceTest {
    private DiscountService service;

    @BeforeEach
    void setUp() {
        service = new DiscountService();
    }

    @Test
    void shouldApplyTwentyPercentForVipCustomers() {
        var discount = service.calculateDiscount(100.0, "VIP");
        assertEquals(20.0, discount);  // Catches if formula changes
    }

    @Test
    void shouldApplyTenPercentForRegularCustomers() {
        var discount = service.calculateDiscount(100.0, "REGULAR");
        assertEquals(10.0, discount);
    }

    @Test
    void shouldReturnZeroForUnknownCustomerTypes() {
        var discount = service.calculateDiscount(100.0, "GUEST");
        assertEquals(0.0, discount);  // Edge case protection
    }
}

