// GOOD: Descriptive name, single behavior, independent
@Test
void shouldCalculateTotalPriceForMultipleItems() {
    // Arrange: set up test data
    var service = new OrderService();
    var order = new Order(1L, List.of(
        new LineItem("Laptop", 1000.0),
        new LineItem("Mouse", 50.0)
    ));

    // Act: execute the behavior being tested
    var total = service.calculateTotal(order);

    // Assert: verify the result
    assertEquals(1050.0, total);
}

@Test
void shouldApplyTenPercentDiscountForOrdersOverThousandDollars() {
    var service = new OrderService();
    var order = new Order(2L, List.of(
        new LineItem("Server", 1200.0)
    ));

    var totalWithDiscount = service.calculateTotal(order);

    assertEquals(1080.0, totalWithDiscount);  // 1200 - 10% = 1080
}

class PaymentProcessor {
    public String processPayment(double amount, String method) {
        if (amount <= 0) {
            return "INVALID_AMOUNT";  // Line 3
        }
        if (method.equals("CREDIT")) {
            return chargeCreditCard(amount);  // Line 6
        } else if (method.equals("DEBIT")) {
            return chargeDebitCard(amount);  // Line 8
        }
        return "UNSUPPORTED_METHOD";  // Line 10
    }
    private String chargeCreditCard(double amount) { return "CREDIT_OK"; }
    private String chargeDebitCard(double amount) { return "DEBIT_OK"; }
}

// BAD TEST: 100% line coverage but doesn't verify correctness
@Test
void testPaymentProcessor() {
    var processor = new PaymentProcessor();
    processor.processPayment(-10, "CREDIT");  // Hits line 3
    processor.processPayment(100, "CREDIT");  // Hits line 6
    processor.processPayment(100, "DEBIT");   // Hits line 8
    processor.processPayment(100, "CASH");    // Hits line 10
    // No assertions! 100% coverage but test proves nothing
}

// GOOD TEST: Lower coverage but actually verifies behavior
@Test
void shouldRejectNegativePaymentAmounts() {
    var processor = new PaymentProcessor();
    var result = processor.processPayment(-10, "CREDIT");
    assertEquals("INVALID_AMOUNT", result);  // Verifies behavior
}

@Test
void shouldProcessCreditCardPaymentsSuccessfully() {
    var processor = new PaymentProcessor();
    var result = processor.processPayment(100.0, "CREDIT");
    assertEquals("CREDIT_OK", result);  // Verifies behavior
}
